import arkenv from "arkenv";

export const env = arkenv({
  HOST: "string.ip | 'localhost'",
  PORT: "1 <= number.integer <= 65535",
  DEBUG: "boolean",
  NODE_ENV: "'development' | 'production' | 'test'",
  ALLOWED_ORIGINS: "string.url[]",
});

import { env } from "../src/env.js";

const output = {
  HOST: env.HOST,
  PORT: env.PORT,
  DEBUG: env.DEBUG,
  NODE_ENV: env.NODE_ENV,
  ALLOWED_ORIGINS: env.ALLOWED_ORIGINS,
  types: {
    PORT: typeof env.PORT,
    DEBUG: typeof env.DEBUG,
    ALLOWED_ORIGINS_IS_ARRAY: Array.isArray(env.ALLOWED_ORIGINS),
  },
};

console.log(`ENV_JSON=${JSON.stringify(output)}`);
